package com.footballacademy.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="player_attribute_snapshots", indexes={@Index(name="idx_snapshot_player", columnList="player_id"),@Index(name="idx_snapshot_match", columnList="match_id")})
public class PlayerAttributeSnapshot { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="player_id") @JsonIgnore private Player player; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="match_id") @JsonIgnore private Match match; private LocalDateTime capturedAt=LocalDateTime.now(); private Double speed,acceleration,agility,stamina,strength,positioning,decisionMaking,vision,offBallMovement,composure; public double overallIndex(){Double[] a={speed,acceleration,agility,stamina,strength,positioning,decisionMaking,vision,offBallMovement,composure}; double s=0; int c=0; for(Double d:a){if(d!=null){s+=d;c++;}} return c==0?0:Math.round((s/c)*100.0)/100.0;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public Player getPlayer(){return player;} public void setPlayer(Player player){this.player=player;} public Match getMatch(){return match;} public void setMatch(Match match){this.match=match;} public LocalDateTime getCapturedAt(){return capturedAt;} public void setCapturedAt(LocalDateTime capturedAt){this.capturedAt=capturedAt;} public Double getSpeed(){return speed;} public void setSpeed(Double v){speed=v;} public Double getAcceleration(){return acceleration;} public void setAcceleration(Double v){acceleration=v;} public Double getAgility(){return agility;} public void setAgility(Double v){agility=v;} public Double getStamina(){return stamina;} public void setStamina(Double v){stamina=v;} public Double getStrength(){return strength;} public void setStrength(Double v){strength=v;} public Double getPositioning(){return positioning;} public void setPositioning(Double v){positioning=v;} public Double getDecisionMaking(){return decisionMaking;} public void setDecisionMaking(Double v){decisionMaking=v;} public Double getVision(){return vision;} public void setVision(Double v){vision=v;} public Double getOffBallMovement(){return offBallMovement;} public void setOffBallMovement(Double v){offBallMovement=v;} public Double getComposure(){return composure;} public void setComposure(Double v){composure=v;} }
